(()=>{'use strict';const KEY='chao-portfolio-draft-v1';const empty=()=>({version:1,changes:{},orders:{},metadata:{}});let state=empty(),server=null,baseCache=new WeakMap(),assetURLs=new Map();const clone=x=>JSON.parse(JSON.stringify(x));const dbPromise=new Promise(resolve=>{try{const req=indexedDB.open('chao-portfolio-assets',1);req.onupgradeneeded=()=>req.result.createObjectStore('assets',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null)}catch{resolve(null)}});const dbAction=async(mode,run)=>{const db=await dbPromise;if(!db)throw new Error('浏览器无法存储图片，请使用本地编辑服务。');return new Promise((resolve,reject)=>{const tx=db.transaction('assets',mode),req=run(tx.objectStore('assets'));req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})};const safeStyle=new Set(['color','font-size','font-family','font-weight','font-style','text-align','letter-spacing','line-height','object-fit','object-position','left','top','width','height','border-radius','opacity','transform']);function cleanStyle(style){const out={};for(const [key,value]of Object.entries(style||{})){if(safeStyle.has(key)&&!/[<>]|url\s*\(|expression\s*\(/i.test(String(value)))out[key]=String(value).slice(0,160)}return out}function sanitize(input){const doc=new DOMParser().parseFromString('<div>'+String(input)+'</div>','text/html'),root=doc.body.firstElementChild;const allowed=new Set(['BR','B','STRONG','I','EM','U','S','SPAN']);for(const node of [...root.querySelectorAll('*')].reverse()){if(['SCRIPT','STYLE','IFRAME','OBJECT','EMBED','SVG','MATH'].includes(node.tagName)){node.remove();continue}if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);continue}for(const a of [...node.attributes]){if(a.name==='style'){const st={};for(const key of safeStyle){const val=node.style.getPropertyValue(key);if(val)st[key]=val}node.removeAttribute('style');Object.entries(cleanStyle(st)).forEach(([k,v])=>node.style.setProperty(k,v))}else if(a.name!=='class'&&a.name!=='data-edit-key'&&a.name!=='data-edit-kind')node.removeAttribute(a.name)}}return root.innerHTML}function safeHref(value){const v=String(value).trim();return /^(https?:|mailto:|tel:|#)/i.test(v)||(!/^[a-z]+:/i.test(v)&&!v.startsWith('//')&&!v.includes('..'))?v:''}function merge(a,b){const out=clone(a);for(const kind of ['changes','orders','metadata'])for(const [page,items]of Object.entries(b[kind]||{})){out[kind][page]??={};for(const [key,val]of Object.entries(items||{})){if(val===null)delete out[kind][page][key];else out[kind][page][key]=val}}return out}const ready=(async()=>{try{const response=await fetch('content-overrides.json',{cache:'no-store'});if(response.ok)state=merge(state,await response.json())}catch{}try{const draft=JSON.parse(localStorage.getItem(KEY)||'null');if(draft)state=merge(state,draft)}catch{}return state})();async function status(){if(server!==null)return server;try{const r=await fetch('/api/editor/status',{cache:'no-store'});server=r.ok?await r.json():false}catch{server=false}return server}function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{}}async function asset(id){return dbAction('readonly',s=>s.get(id))}async function source(src,exportAssets){if(!src?.startsWith('idb:'))return src;const id=src.slice(4),item=await asset(id);if(!item)return '';if(exportAssets){const ext=item.mime?.split('/')[1]?.replace('jpeg','jpg')||'png';const path='assets/uploads/'+id+'.'+ext;exportAssets.set(path,item.blob);return path}if(!assetURLs.has(id))assetURLs.set(id,URL.createObjectURL(item.blob));return assetURLs.get(id)}function captureBases(doc){if(baseCache.has(doc))return baseCache.get(doc);const bases=new Map();doc.querySelectorAll('[data-edit-key]').forEach(el=>{const key=el.dataset.editKey;const record={html:el.innerHTML,style:el.getAttribute('style'),src:el.getAttribute('src'),alt:el.getAttribute('alt'),href:el.getAttribute('href'),hidden:el.hidden,figureHidden:el.closest('figure')?.hidden};if(!bases.has(key))bases.set(key,[]);bases.get(key).push(record)});bases.orders=[...doc.querySelectorAll('[data-edit-parent]')].map(p=>({key:p.dataset.editParent,children:[...p.children].map(e=>e.dataset.editBlock).filter(Boolean)}));baseCache.set(doc,bases);return bases}function elements(doc,key){return [...doc.querySelectorAll('[data-edit-key]')].filter(el=>el.dataset.editKey===key)}async function apply(doc,page,options={}){await ready;const viewing=!new URLSearchParams(location.search).has('edit')&&!doc.body?.classList.contains('site-editor');if(viewing&&!options.reset&&!options.exportAssets&&!Object.keys(state.changes['*']||{}).length&&!Object.keys(state.changes[page]||{}).length&&!Object.keys(state.orders||{}).length)return;const bases=captureBases(doc);if(options.reset){for(const [key,values]of bases)elements(doc,key).forEach((el,i)=>{const b=values[i]||values[0];if(el.dataset.editKind!=='image')el.innerHTML=b.html;for(const name of ['style','src','alt','href'])b[name]===null?el.removeAttribute(name):el.setAttribute(name,b[name]);el.hidden=b.hidden;if(el.closest('figure')&&b.figureHidden!==undefined)el.closest('figure').hidden=b.figureHidden})}if(options.reset)for(const order of bases.orders){const p=doc.querySelector('[data-edit-parent="'+CSS.escape(order.key)+'"]');if(p)for(const key of order.children){const child=[...p.children].find(e=>e.dataset.editBlock===key);if(child)p.append(child)}}for(const layer of ['*',page]){for(const [key,change]of Object.entries(state.changes[layer]||{})){if(!change)continue;for(const el of elements(doc,key)){if('html'in change&&el.dataset.editKind!=='image'){el.innerHTML=sanitize(change.html);const mail=el.closest('a[href^="mailto:"]');const address=el.textContent.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(mail&&address)mail.setAttribute('href','mailto:'+address[0])}if(change.src&&el.tagName==='IMG'){const url=await source(change.src,options.exportAssets);if(url){el.src=url;el.style.setProperty('transform','none','important')}}if('alt'in change&&el.tagName==='IMG')el.alt=change.alt;if('href'in change&&el.tagName==='A'){el.setAttribute('href',safeHref(change.href));if(/^mailto:/i.test(change.href)){const address=change.href.slice(7).split('?')[0];const walk=doc.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){if(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(node.textContent))node.textContent=node.textContent.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i,address)}}}for(const [name,value]of Object.entries(cleanStyle(change.style)))el.style.setProperty(name,value,'important');if('hidden'in change){const holder=el.tagName==='IMG'?el.closest('figure')||el:el;holder.hidden=!!change.hidden}}}for(const [parentKey,keys]of Object.entries(state.orders[layer]||{})){const parent=doc.querySelector('[data-edit-parent="'+CSS.escape(parentKey)+'"]');if(parent)for(const key of keys){const block=[...parent.children].find(n=>n.dataset.editBlock===key);if(block)parent.append(block)}}const meta=state.metadata[layer];if(meta?.title)doc.title=meta.title}for(const figure of doc.querySelectorAll('.ed-figure')){const button=figure.querySelector('.image-enlarge'),caption=figure.querySelector('figcaption>span');if(button&&caption){button.dataset.caption=caption.textContent;button.setAttribute('aria-label','放大：'+caption.textContent)}}return doc}function update(page,key,change){state.changes[page]??={};state.changes[page][key]=change===null?null:{...(state.changes[page][key]||{}),...change};persist();return state}function replace(next){state=clone(next);persist()}async function upload(file){const head=new Uint8Array(await file.slice(0,16).arrayBuffer());let mime=file.type;if(head[0]===255&&head[1]===216&&head[2]===255)mime='image/jpeg';else if(head[0]===137&&head[1]===80&&head[2]===78&&head[3]===71)mime='image/png';else if(String.fromCharCode(...head.slice(0,3))==='GIF')mime='image/gif';else if(String.fromCharCode(...head.slice(0,4))==='RIFF'&&String.fromCharCode(...head.slice(8,12))==='WEBP')mime='image/webp';if(!mime.startsWith('image/'))throw new Error('请选择图片文件。');if(file.size>25*1024*1024)throw new Error('图片需小于 25 MB。');const api=await status();if(api?.available){const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const r=await fetch('/api/editor/asset',{method:'POST',headers:{'Content-Type':'application/json','X-Editor-Token':api.token},body:JSON.stringify({name:file.name,mime,data})});const result=await r.json();if(!r.ok)throw new Error(result.error||'图片保存失败');return result.path}const id=crypto.randomUUID();await dbAction('readwrite',s=>s.put({id,blob:file,mime,name:file.name}));return 'idb:'+id}async function save(previous){const api=await status();if(!api?.available){persist();return {local:true}}const payload=clone(state);delete payload.version;for(const entries of Object.values(payload.changes))for(const change of Object.values(entries)){if(change?.src&&change.style?.transform==='none')delete change.style.transform;}for(const kind of ['changes','orders','metadata'])for(const [page,values]of Object.entries(previous?.[kind]||{})){payload[kind][page]??={};for(const key of Object.keys(values))if(!(key in payload[kind][page]))payload[kind][page][key]=null}const r=await fetch('/api/editor/save',{method:'POST',headers:{'Content-Type':'application/json','X-Editor-Token':api.token},body:JSON.stringify(payload)});const result=await r.json();if(!r.ok)throw new Error(result.error||'保存失败');if(result.content)state=merge(empty(),result.content);localStorage.removeItem(KEY);return result}async function reset(){const api=await status();if(api?.available){const r=await fetch('/api/editor/reset',{method:'POST',headers:{'Content-Type':'application/json','X-Editor-Token':api.token},body:'{}'});if(!r.ok)throw new Error('重置失败')}state=empty();localStorage.removeItem(KEY)}async function exportSite(progress=()=>{}){await ready;if(!window.JSZip)throw new Error('导出组件未加载');const manifest=await(await fetch('site-files.json',{cache:'no-store'})).json(),zip=new JSZip(),assets=new Map();let count=0;const files=manifest.files.filter(path=>!path.startsWith('.')&&path!=='site-files.json');const queue=[...files];async function worker(){while(queue.length){const path=queue.shift(),res=await fetch(path,{cache:'no-store'});if(!res.ok)throw new Error('无法读取 '+path);if(path.endsWith('.html')){const text=await res.text(),doc=new DOMParser().parseFromString(text,'text/html');await apply(doc,path,{exportAssets:assets});doc.querySelectorAll('[data-chao-selected],[contenteditable]').forEach(e=>{e.removeAttribute('data-chao-selected');e.removeAttribute('contenteditable')});zip.file(path,'<!doctype html>\n'+doc.documentElement.outerHTML)}else if(path==='content-overrides.json'){/* written after image resolution */}else if(path==='tools/serve-editable.py'){zip.file('serve-editable.py',await res.text())}else zip.file(path,await res.arrayBuffer());count++;progress(count,files.length)}}await Promise.all(Array.from({length:6},worker));const exported=clone(state);for(const changes of Object.values(exported.changes))for(const change of Object.values(changes)){if(change?.src?.startsWith('idb:'))change.src=await source(change.src,assets)}for(const [path,blob]of assets)zip.file(path,blob);zip.file('content-overrides.json',JSON.stringify(exported,null,2));zip.file('site-files.json',JSON.stringify({files:[...new Set([...files.filter(p=>p!=='tools/serve-editable.py'),'serve-editable.py','site-files.json',...assets.keys()])]},null,2));zip.file('使用说明.txt','打开可视化编辑器：\n1. 在本文件夹运行 python3 serve-editable.py --port 8765 --open\n2. 浏览器访问 http://localhost:8765/editor.html\n3. 文字、图片、链接和模块顺序均可点选修改。保存会写入当前网站。\n4. 导出网站 ZIP 可备份或交给部署人员。\n\n如 8765 被占用，可改为 --port 8766。');const blob=await zip.generateAsync({type:'blob',compression:'STORE'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Chao-editable-portfolio.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);return blob}window.ChaoContent={ready,get state(){return state},status,sanitize,cleanStyle,safeHref,apply,update,replace,upload,save,reset,exportSite,clone};if(!document.body.classList.contains('site-editor'))ready.then(()=>apply(document,location.pathname.split('/').pop()||'index.html')).catch(()=>{});})();
